const agentData = $input.first().json.output || $input.first().json;

if (!agentData || !agentData.proposal) {
  throw new Error('Agent-Output ungueltig oder kein proposal-Feld: ' + JSON.stringify(agentData).slice(0, 200));
}

const state = $('Parse LLM output to JSON').first().json.state;
const anfrage = state.anfrage;
const pauschale = $('Prepare Budget').first().json.pauschale || 200;
const guestCount = anfrage.personenanzahl;
const budget = anfrage.budget;

let menuGesamtpreis = 0;

const proposal = agentData.proposal.map(function(item) {
  const count = item.count || guestCount;
  const totalPrice = Math.round(item.pricePerPerson * count * 100) / 100;
  menuGesamtpreis += totalPrice;
  return {
    menuItemId: item.menuItemId,
    name: item.name,
    category: item.category,
    count: count,
    pricePerPerson: Math.round(item.pricePerPerson * 100) / 100,
    totalPrice: totalPrice,
    reason: item.reason || ''
  };
});

menuGesamtpreis = Math.round(menuGesamtpreis * 100) / 100;
const totalCosts = Math.round((menuGesamtpreis + pauschale) * 100) / 100;
const budgetEingehalten = totalCosts <= budget;

const summary = {
  proposal, guestCount, menuGesamtpreis,
  verwaltungspauschale: pauschale, totalCosts, budget,
  budgetEingehalten, reason: agentData.reason || ''
};

const lines = [
  '────────────────────────────────────',
  '  AUSGEWAEHLTE GERICHTE',
  '────────────────────────────────────',
  ''
].concat(proposal.map(function(i, idx) {
  return '  ' + (idx + 1) + '. ' + i.name +
    '\n     Kategorie: ' + i.category +
    '\n     Preis/Pers: EUR ' + i.pricePerPerson.toFixed(2) +
    '\n     Anzahl: ' + i.count + ' Personen' +
    '\n     Gesamt: EUR ' + i.totalPrice.toFixed(2) +
    '\n';
})).concat([
  '────────────────────────────────────',
  '  KOSTENUEBERSICHT',
  '────────────────────────────────────',
  '',
  '  Menuepreise gesamt:      EUR ' + menuGesamtpreis.toFixed(2),
  '  Verwaltungspauschale:   EUR ' + pauschale.toFixed(2),
  '  ─────────────────────────────',
  '  GESAMTPREIS:            EUR ' + totalCosts.toFixed(2),
  '  Budget:                 EUR ' + budget.toFixed(2),
  '',
  '  Budget eingehalten:  ' + (budgetEingehalten ? 'JA' : 'NEIN - Ueberschreitung!'),
  '',
  '────────────────────────────────────',
  '  BEGRUENDUNG',
  '────────────────────────────────────',
  '',
  '  ' + (summary.reason || '(keine)'),
  '',
  '════════════════════════════════════'
]);

return [{ json: Object.assign({}, summary, { emailBody: lines.join('\n'), state }) }];

